class TrustedClientIsResourceServerAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that isIsResourceServer returns null on a freshly created holder.
     */
    public function testIsResourceServerNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientIsResourceServerAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isIsResourceServerAssigned());
        $this->assertNull($holder->isIsResourceServer());
    }
}
